        ("2 players · classic table", ["2 jugadores · mesa clásica", "لاعبان · طاولة تقليدية", "2 खिलाड़ी · क्लासिक टेबल", "2 spelers · klassieke tafel"]),
        ("3 players · Y table", ["3 jugadores · mesa en Y", "3 لاعبين · طاولة Y", "3 खिलाड़ी · Y टेबल", "3 spelers · Y-tafel"]),
        ("4 players · cross table", ["4 jugadores · mesa en cruz", "4 لاعبين · طاولة متقاطعة", "4 खिलाड़ी · क्रॉस टेबल", "4 spelers · kruistafel"]),
        ("3 players (Y table)", ["3 jugadores (mesa en Y)", "3 لاعبين (طاولة Y)", "3 खिलाड़ी (Y टेबल)", "3 spelers (Y-tafel)"]),
        ("4 players (cross table)", ["4 jugadores (mesa en cruz)", "4 لاعبين (طاولة متقاطعة)", "4 खिलाड़ी (क्रॉस टेबल)", "4 spelers (kruistafel)"]),
        ("Cross table · 4 seats", ["Mesa en cruz · 4 plazas", "طاولة متقاطعة · 4 أماكن", "क्रॉस टेबल · 4 जगहें", "Kruistafel · 4 plekken"]),
