        ("Raise", ["Elevar", "ارفع", "ऊँचा उठाएँ", "Hoog spelen"]),
        ("Paused", ["En pausa", "متوقف مؤقتًا", "रुका हुआ", "Gepauzeerd"]),
        ("Swipe now to smash!", ["¡Desliza ahora para rematar!", "اسحب الآن لضربة ساحقة!", "स्मैश के लिए अभी स्वाइप करें!", "Veeg nu voor een smash!"]),
        ("Tap the called court to serve", ["Toca la zona indicada para sacar", "المس المنطقة المحددة للإرسال", "सर्व करने के लिए बताए कोर्ट पर टैप करें", "Tik op het aangewezen vlak om te serveren"]),
